<template>
  <div class="page-head"><div><h2>风险研判</h2><span class="muted">基于积水识别与时空变化成果进行规则化辅助研判。</span></div><n-button v-if="current&&!aiRunning" @click="explain">生成规则说明</n-button><n-button v-else-if="aiRunning" @click="stopAI">停止生成</n-button></div>
  <n-tabs v-model:value="tab" type="segment" animated>
    <n-tab-pane name="create" tab="新建研判">
      <n-card title="数据来源" class="source-card">
        <div class="source-form"><n-select v-model:value="changeId" filterable :options="changeOptions" placeholder="选择已完成的时空变化分析" @update:value="loadSource"/><n-input v-model:value="assessmentName" maxlength="255" placeholder="研判名称（可选）"/><n-button type="primary" :disabled="!changeId" :loading="creating" @click="create">开始基础水害研判</n-button></div>
        <n-descriptions v-if="source" bordered :column="5" size="small" style="margin-top:14px"><n-descriptions-item label="T1 → T2">{{source.t1.dataset_name}} → {{source.t2.dataset_name}}</n-descriptions-item><n-descriptions-item label="当前积水">{{pct(source.t2.water_ratio)}}</n-descriptions-item><n-descriptions-item label="新增积水">{{pct(source.ratios.new_water)}}</n-descriptions-item><n-descriptions-item label="持续积水">{{pct(source.ratios.persistent_water)}}</n-descriptions-item><n-descriptions-item label="净变化">{{signed(source.net_change_ratio)}}</n-descriptions-item></n-descriptions>
      </n-card>
    </n-tab-pane>
    <n-tab-pane name="history" tab="研判历史"><n-card><div class="history-head"><span>共 {{history.length}} 条正式辅助研判记录</span><n-button :loading="loadingHistory" @click="loadHistory">刷新</n-button></div><n-data-table :columns="columns" :data="history" :loading="loadingHistory" :pagination="{pageSize:10}" :scroll-x="1050"/></n-card></n-tab-pane>
  </n-tabs>

  <n-card v-if="!current&&tab==='create'" class="onboarding-panel">
    <div class="onboarding-content"><div class="onboarding-mark"><img src="/icons/shield-search.svg" alt=""></div><h3>从已完成的变化分析建立风险研判</h3><p>选择一条真实的时空变化成果，系统将按固定规则生成可追溯的基础水害关注等级与研判依据。</p><div class="onboarding-steps"><div><b>1. 选择成果</b><span>使用已完成的 T1→T2 变化分析</span></div><div><b>2. 生成研判</b><span>记录规则版本、空间结果与统计依据</span></div><div><b>3. 关联现场</b><span>继续分析区域、设备并创建核查事项</span></div></div><n-button @click="$router.push('/compare')">前往时空变化分析</n-button></div>
  </n-card>

  <n-spin :show="loadingDetail"><section v-if="current&&current.status==='completed'" class="result-section">
    <div class="result-head"><h3>{{current.assessment_name}}</h3><n-space><n-button type="primary" :loading="assistanceRunning" @click="generateAssistance">生成作业事项</n-button><n-button tag="a" :href="api.riskCsvUrl(current.id)" download>CSV</n-button><n-button tag="a" :href="current.geotiff_url||undefined" download>GeoTIFF</n-button><n-button tag="a" :href="api.riskHtmlUrl(current.id)" target="_blank">报告</n-button><n-button tag="a" :href="api.riskPdfUrl(current.id)" download>PDF</n-button></n-space></div>
    <n-alert v-if="assistanceHint" type="info" style="margin-bottom:14px">{{assistanceHint}} <n-button text type="primary" @click="$router.push('/assistance')">前往作业辅助中心</n-button></n-alert>
    <n-card title="项目范围" class="impact-action-card">
      <div class="impact-action"><n-select v-model:value="impactProjectId" :options="projectOptions" filterable clearable placeholder="选择施工项目"/><n-button type="primary" :disabled="!impactProjectId" :loading="impactRunning" @click="runImpacts">分析区域影响</n-button></div>
      <n-alert v-if="impactHint" type="info" style="margin-top:12px">{{impactHint}}</n-alert>
    </n-card>
    <n-card title="研判概况" class="risk-overview">
      <div class="overview-layout">
        <div class="level-panel"><span>水害关注等级</span><strong :class="['attention',levelClass]">{{current.attention_level}}</strong></div>
        <div class="ratio-list"><span>当前积水 <b>{{pct(current.current_water_ratio)}}</b></span><span>新增积水 <b>{{pct(current.new_water_ratio)}}</b></span><span>持续积水 <b>{{pct(current.persistent_water_ratio)}}</b></span><span>消退积水 <b>{{pct(current.receded_water_ratio)}}</b></span><span>净变化 <b>{{signed(current.net_change_ratio)}}</b></span></div>
        <ul class="reason-list"><li v-for="reason in current.risk_reason_text" :key="reason">{{reason}}</li></ul>
      </div>
      <div class="decision-boundary">该等级用于水害关注研判，不等同于施工安全等级。</div>
    </n-card>
    <n-card title="空间判读" class="spatial-card"><template #header-extra><div class="legend"><span class="high">高关注</span><span class="inspect">重点巡检</span><span class="general">一般区域</span></div></template><div class="four-images"><figure><figcaption>T1 积水</figcaption><div class="preview-box"><img v-if="taskImage(t1Task)" :src="taskImage(t1Task)"></div></figure><figure><figcaption>T2 积水</figcaption><div class="preview-box"><img v-if="taskImage(t2Task)" :src="taskImage(t2Task)"></div></figure><figure><figcaption>积水变化</figcaption><div class="preview-box"><img v-if="source?.image_url" :src="source.image_url"></div></figure><figure><figcaption>水害关注区域</figcaption><div class="preview-box"><img v-if="current.image_url" :src="current.image_url"></div></figure></div></n-card>
    <n-card v-if="impacts.length" title="作业区域水害空间影响" class="impact-table-card"><n-data-table :columns="impactColumns" :data="impacts" :pagination="false" :scroll-x="1050"/><p class="zone-note">影响等级仅反映作业区域与本次水害关注栅格的空间叠加结果，不等同于综合施工安全等级。</p></n-card>
    <n-card title="工程机械水害关联" class="impact-table-card"><div class="equipment-action"><n-button type="primary" :disabled="!current.project_id" :loading="equipmentRunning" @click="runEquipmentLinks">分析工程机械水害关联</n-button><n-button v-if="equipmentLinks.length" tag="a" :href="api.equipmentLinksCsvUrl(current.id)" download>导出设备关联CSV</n-button><span class="muted">仅分析所属项目内启用且已有最近位置快照的设备；无位置设备不会生成结果。</span></div><n-data-table v-if="equipmentLinks.length" :columns="equipmentColumns" :data="equipmentLinks" :pagination="false" :scroll-x="1300" style="margin-top:14px"/><n-empty v-else description="暂无工程机械水害关联结果"/><p class="zone-note">设备位置为时间点快照；点位水害类别与施工区域整体影响等级分别展示，不代表车辆安全状态或可通行性。</p></n-card>
    <n-card title="地形辅助分析" class="impact-table-card"><div class="terrain-action"><n-select v-model:value="terrainDemId" :options="terrainOptions" filterable clearable placeholder="选择当前项目DEM"/><n-button type="primary" :disabled="!terrainDemId" :loading="terrainRunning" @click="runTerrain">分析地形关系</n-button><n-button v-if="terrainFusions.length" tag="a" :href="api.terrainFusionCsvUrl(current.id)" download>导出地形融合CSV</n-button></div><n-data-table v-if="terrainFusions.length" :columns="terrainColumns" :data="terrainRows" :pagination="false" style="margin-top:14px"/><n-empty v-else description="暂无地形融合分析结果"/><p class="zone-note">地形辅助信息不会改变 water-risk-v1 正式关注等级；相对低高程不表示必然积水，坡度不表示工程机械通行安全。</p></n-card>
    <n-card title="降雨背景信息" class="impact-table-card"><div class="equipment-action"><n-button type="primary" :disabled="!current.project_id" :loading="rainRunning" @click="runRain">生成/更新降雨背景</n-button><n-button v-if="rainContext" tag="a" :href="api.riskRainfallCsvUrl(current.id)" download>导出降雨背景CSV</n-button></div><n-descriptions v-if="rainContext" bordered :column="3" size="small" style="margin-top:14px"><n-descriptions-item label="时间窗口">{{fmt(rainContext.window_start)}} 至 {{fmt(rainContext.window_end)}}</n-descriptions-item><n-descriptions-item label="累计降雨">{{rainContext.total_rainfall_mm==null?'无对应观测':rainContext.total_rainfall_mm.toFixed(2)+' mm'}}</n-descriptions-item><n-descriptions-item label="事件数量">{{rainContext.rainfall_event_count}}</n-descriptions-item><n-descriptions-item label="峰值时段平均雨强">{{rainContext.peak_rainfall_rate_mm_h==null?'--':rainContext.peak_rainfall_rate_mm_h.toFixed(2)+' mm/h'}}</n-descriptions-item><n-descriptions-item label="最近事件">{{fmt(rainContext.latest_event_start||null)}} 至 {{fmt(rainContext.latest_event_end||null)}}</n-descriptions-item><n-descriptions-item label="数据完整状态">{{rainContext.coverage_label}}</n-descriptions-item></n-descriptions><n-empty v-else description="暂无降雨背景分析"/><p class="zone-note">降雨仅作为历史环境背景，不改变 water-risk-v1 正式等级；同期存在不等于已验证因果关系。</p></n-card>
    <n-card title="无人机精细复核" class="impact-table-card">
      <div class="terrain-action"><n-select v-model:value="uavDatasetId" :options="uavOptions" filterable clearable placeholder="选择所属项目无人机正射影像"/><n-button type="primary" :disabled="!uavDatasetId" :loading="uavRunning" @click="runUavOverlay">分析风险区域覆盖</n-button><n-button tag="a" :href="api.uavOverlayCsvUrl(current.id)" download>导出覆盖CSV</n-button></div>
      <n-data-table v-if="uavOverlays.length" :columns="uavOverlayColumns" :data="uavOverlays" :pagination="false" style="margin-top:14px"/>
      <div v-if="uavOverlays.length" class="uav-gallery"><figure v-for="item in uavOverlays" :key="item.id"><img :src="item.high_attention_crop_url||item.inspection_crop_url||''"><figcaption>{{item.uav_name}} · {{item.uav_capture_time?fmt(item.uav_capture_time):'采集时间未填写'}}</figcaption></figure></div>
      <n-empty v-else description="暂无无人机风险区域覆盖分析"/>
      <n-divider title-placement="left">创建人工复核记录</n-divider>
      <div class="verification-form"><n-select v-model:value="verificationForm.uav_dataset_id" :options="uavOptions" placeholder="无人机影像"/><n-select v-model:value="verificationForm.work_area_id" :options="impactAreaOptions" clearable placeholder="施工区域（可选）"/><n-select v-model:value="verificationForm.verification_status" :options="verificationStatusOptions"/><n-select v-model:value="verificationForm.observation_type" :options="observationOptions"/><n-input v-model:value="verificationForm.finding_text" type="textarea" placeholder="人工观察说明（不自动生成）"/><n-input v-model:value="verificationForm.recommendation_text" type="textarea" placeholder="辅助建议（不得直接作通行结论）"/><n-button type="primary" :disabled="!verificationForm.uav_dataset_id" @click="saveVerification">保存人工复核</n-button></div>
      <n-data-table v-if="uavVerifications.length" :columns="verificationColumns" :data="uavVerifications" :pagination="{pageSize:6}" style="margin-top:14px"/>
      <p class="zone-note">无人机影像用于局部精细查看和人工复核，不是实时监控或自动AI识别；覆盖不等于确认，人工观察不修改 water-risk-v1 正式等级。</p>
    </n-card>
    <div class="two-col advice-row"><n-card title="辅助建议"><ul><li v-for="item in current.inspection_advice" :key="item">{{item}}</li></ul></n-card><n-card title="使用边界"><p>{{current.boundary_note}}</p></n-card></div>
    <n-card v-if="aiText||aiRunning" title="智盾助手 · 规则解释" class="ai-card"><n-skeleton v-if="aiRunning&&!aiText" text :repeat="4"/><div v-if="aiText" v-html="safeMarkdown(aiText)"></div><p>AI只解释规则结论，不能改变正式关注等级。</p></n-card>
  </section></n-spin>
</template>

<script setup lang="ts">
import { computed,h,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { NButton,NPopconfirm,NTag,useMessage } from 'naive-ui'
import { api,streamRiskAI } from '../api'
import type { ChangeAnalysis,ConstructionProject,EquipmentRiskLink,RainfallContext,RiskAssessment,Task,TerrainDataset,TerrainFusion,UavDataset,UavRiskOverlay,UavVerification,WorkAreaImpact } from '../types'
import { formatDateTime } from '../utils/format'
import { safeMarkdown } from '../utils/markdown'
import { currentProjectId } from '../composables/projectContext'
const msg=useMessage(),tab=ref<'create'|'history'>('create'),changes=ref<ChangeAnalysis[]>([]),history=ref<RiskAssessment[]>([]),projects=ref<ConstructionProject[]>([]),dems=ref<TerrainDataset[]>([]),uavDatasets=ref<UavDataset[]>([]),uavOverlays=ref<UavRiskOverlay[]>([]),uavVerifications=ref<UavVerification[]>([]),uavDatasetId=ref<string|null>(null),uavRunning=ref(false),terrainFusions=ref<TerrainFusion[]>([]),terrainDemId=ref<string|null>(null),rainContext=ref<RainfallContext|null>(null),impacts=ref<WorkAreaImpact[]>([]),equipmentLinks=ref<EquipmentRiskLink[]>([]),impactProjectId=ref<string|null>(null),impactRunning=ref(false),equipmentRunning=ref(false),terrainRunning=ref(false),rainRunning=ref(false),assistanceRunning=ref(false),assistanceHint=ref(''),impactHint=ref(''),changeId=ref<string|null>(null),assessmentName=ref(''),source=ref<ChangeAnalysis|null>(null),current=ref<RiskAssessment|null>(null),t1Task=ref<Task|null>(null),t2Task=ref<Task|null>(null),creating=ref(false),loadingHistory=ref(false),loadingDetail=ref(false),aiRunning=ref(false),aiText=ref('')
const verificationForm=ref({uav_dataset_id:null as string|null,work_area_id:null as string|null,verification_status:'PENDING',observation_type:'OTHER',finding_text:'',recommendation_text:''})
let controller:AbortController|null=null,aiVersion=0
const changeOptions=computed(()=>changes.value.filter(x=>x.status==='completed').map(x=>({label:`${x.name} · ${formatDateTime(x.completed_at)}`,value:x.id})))
const projectOptions=computed(()=>projects.value.filter(x=>x.status==='active').map(x=>({label:`${x.project_name} · ${x.project_code}`,value:x.id})))
const terrainOptions=computed(()=>dems.value.filter(x=>!x.project_id||x.project_id===current.value?.project_id).map(x=>({label:`${x.name} · ${x.crs}`,value:x.id})))
const uavOptions=computed(()=>uavDatasets.value.filter(x=>x.project_id===current.value?.project_id).map(x=>({label:`${x.name} · ${x.capture_time?formatDateTime(x.capture_time):'采集时间未填写'}`,value:x.id})))
const impactAreaOptions=computed(()=>impacts.value.map(x=>({label:x.area_name,value:x.work_area_id})))
const verificationStatusOptions=[{label:'待复核',value:'PENDING'},{label:'已复核',value:'REVIEWED'},{label:'影像不足',value:'INSUFFICIENT_IMAGE'}]
const observationOptions=[{label:'可见积水',value:'VISIBLE_WATER'},{label:'疑似积水',value:'POSSIBLE_WATER'},{label:'湿润/泥泞迹象',value:'MUDDY_OR_WET_SURFACE'},{label:'未见明显积水',value:'NO_OBVIOUS_WATER'},{label:'影像不清晰',value:'IMAGE_UNCLEAR'},{label:'其他',value:'OTHER'}]
const terrainRows=computed(()=>terrainFusions.value.flatMap(f=>[{zone:'高水害关注区域',...f.high_attention,dem_name:f.dem_name,version:f.algorithm_version},{zone:'重点巡检区域',...f.inspection,dem_name:f.dem_name,version:f.algorithm_version},{zone:'一般区域',...f.general,dem_name:f.dem_name,version:f.algorithm_version}]))
const levelClass=computed(()=>current.value?.attention_level?.startsWith('高')?'high':current.value?.attention_level?.startsWith('中')?'medium':'low')
const pct=(v:number|null)=>v==null?'--':`${(v*100).toFixed(2)}%`,signed=(v:number|null)=>v==null?'--':`${v>=0?'+':''}${(v*100).toFixed(2)}%`,fmt=(v:string|null)=>v?formatDateTime(v):'--',taskImage=(t:Task|null)=>t?.result?.files.mask_preview||''
async function loadSource(id:string){source.value=await api.changeAnalysis(id);[t1Task.value,t2Task.value]=await Promise.all([api.result(source.value.t1.result_id),api.result(source.value.t2.result_id)])}
async function loadHistory(){loadingHistory.value=true;try{history.value=await api.riskAssessments(currentProjectId.value||undefined)}catch(e:any){msg.error(e.message)}finally{loadingHistory.value=false}}
async function create(){if(!changeId.value)return;creating.value=true;try{const row=await api.createRiskAssessment({source_change_analysis_id:changeId.value,...(assessmentName.value.trim()?{assessment_name:assessmentName.value.trim()}:{})});msg.success('基础水害辅助研判已生成');await loadHistory();await show(row)}catch(e:any){msg.error(e.message)}finally{creating.value=false}}
async function show(row:RiskAssessment){loadingDetail.value=true;stopAI();try{current.value=await api.riskAssessment(row.id);[impacts.value,equipmentLinks.value,terrainFusions.value,rainContext.value,uavOverlays.value,uavVerifications.value]=await Promise.all([api.riskWorkAreaImpacts(row.id),api.riskEquipmentLinks(row.id),api.terrainFusions(row.id),api.riskRainfallContext(row.id),api.riskUavOverlays(row.id),api.uavVerifications(`risk_assessment_id=${encodeURIComponent(row.id)}`)]);if(current.value.project_id)uavDatasets.value=await api.uavDatasets(current.value.project_id);terrainDemId.value=terrainFusions.value[0]?.dem_id||null;uavDatasetId.value=uavOverlays.value[0]?.uav_dataset_id||null;verificationForm.value.uav_dataset_id=uavDatasetId.value;impactProjectId.value=current.value.project_id||impacts.value[0]?.project_id||null;impactHint.value='';if(current.value.source_change_analysis_id){changeId.value=current.value.source_change_analysis_id;await loadSource(changeId.value)}}catch(e:any){msg.error(e.message)}finally{loadingDetail.value=false}}
async function runImpacts(){if(!current.value||!impactProjectId.value)return;impactRunning.value=true;try{impacts.value=await api.runWorkAreaImpacts(current.value.id,impactProjectId.value);impactHint.value=impacts.value.length?`已完成 ${impacts.value.length} 个启用作业区域的空间影响分析。`:'该项目暂无启用的作业区域。';current.value=await api.riskAssessment(current.value.id);msg.success('施工区域影响分析已完成')}catch(e:any){msg.error(e.message)}finally{impactRunning.value=false}}
async function runEquipmentLinks(){if(!current.value)return;equipmentRunning.value=true;try{equipmentLinks.value=await api.runEquipmentLinks(current.value.id);msg.success(equipmentLinks.value.length?`已生成 ${equipmentLinks.value.length} 台设备的水害关联`:'项目内没有同时满足启用且已有位置快照的设备')}catch(e:any){msg.error(e.message)}finally{equipmentRunning.value=false}}
async function runTerrain(){if(!current.value||!terrainDemId.value)return;terrainRunning.value=true;try{await api.runTerrainFusion(current.value.id,terrainDemId.value);terrainFusions.value=await api.terrainFusions(current.value.id);msg.success('风险与地形融合分析已完成')}catch(e:any){msg.error(e.message)}finally{terrainRunning.value=false}}
async function runRain(){if(!current.value)return;rainRunning.value=true;try{rainContext.value=await api.runRiskRainfallContext(current.value.id);msg.success('风险研判降雨背景已更新')}catch(e:any){msg.error(e.message)}finally{rainRunning.value=false}}
async function runUavOverlay(){if(!current.value||!uavDatasetId.value)return;uavRunning.value=true;try{await api.runUavRiskOverlay(current.value.id,uavDatasetId.value);uavOverlays.value=await api.riskUavOverlays(current.value.id);verificationForm.value.uav_dataset_id=uavDatasetId.value;msg.success('无人机与风险区域协同分析已完成')}catch(e:any){msg.error(e.message)}finally{uavRunning.value=false}}
async function saveVerification(){if(!current.value||!current.value.project_id||!verificationForm.value.uav_dataset_id)return;try{await api.createUavVerification({...verificationForm.value,project_id:current.value.project_id,risk_assessment_id:current.value.id});uavVerifications.value=await api.uavVerifications(`risk_assessment_id=${encodeURIComponent(current.value.id)}`);msg.success('人工复核记录已保存')}catch(e:any){msg.error(e.message)}}
async function generateAssistance(){if(!current.value)return;assistanceRunning.value=true;try{const result=await api.generateAssistance(current.value.id);const types=Object.entries(result.type_counts).map(([key,value])=>`${key} ${value}条`).join('、');assistanceHint.value=`新生成 ${result.created_count} 条，已有未闭环 ${result.existing_open_count} 条${types?`；${types}`:''}。`;msg.success('作业辅助事项生成完成')}catch(e:any){msg.error(e.message)}finally{assistanceRunning.value=false}}
async function remove(row:RiskAssessment){try{await api.removeRiskAssessment(row.id);if(current.value?.id===row.id)current.value=null;await loadHistory();msg.success('风险研判记录已删除')}catch(e:any){msg.error(e.message)}}
const columns=[{title:'ID',render:(r:RiskAssessment)=>r.id.slice(0,8),width:90},{title:'研判名称',key:'assessment_name',ellipsis:{tooltip:true},width:220},{title:'来源 T1 → T2',render:(r:RiskAssessment)=>`${r.source_t1_name} → ${r.source_t2_name}`,ellipsis:{tooltip:true},width:240},{title:'当前积水',render:(r:RiskAssessment)=>pct(r.current_water_ratio),width:100},{title:'关注等级',render:(r:RiskAssessment)=>h(NTag,{type:r.attention_level?.startsWith('高')?'error':r.attention_level?.startsWith('中')?'warning':'success'},{default:()=>r.attention_level||'--'}),width:120},{title:'主要原因',render:(r:RiskAssessment)=>r.risk_reason_text.slice(0,2).join('；'),ellipsis:{tooltip:true},width:240},{title:'研判时间',render:(r:RiskAssessment)=>fmt(r.completed_at),width:160},{title:'操作',fixed:'right' as const,width:140,render:(r:RiskAssessment)=>h('div',{style:'display:flex;gap:7px'},[h(NButton,{size:'small',onClick:()=>show(r)},{default:()=>'打开'}),h(NPopconfirm,{onPositiveClick:()=>remove(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除'}),default:()=>'删除该研判及自身成果？'})])}]
const impactColumns=[{title:'作业区域',key:'area_name',width:180},{title:'区域类型',key:'area_type_label',width:110},{title:'有效像素',key:'total_valid_pixels',width:100},{title:'一般区域',render:(r:WorkAreaImpact)=>pct(r.general_ratio),width:110},{title:'重点巡检',render:(r:WorkAreaImpact)=>pct(r.inspection_ratio),width:110},{title:'高水害关注',render:(r:WorkAreaImpact)=>pct(r.high_attention_ratio),width:120},{title:'区域影响等级',render:(r:WorkAreaImpact)=>h(NTag,{type:r.impact_level.startsWith('高')?'error':r.impact_level.startsWith('中')?'warning':'success'},{default:()=>r.impact_level}),width:140},{title:'辅助建议',key:'advice',ellipsis:{tooltip:true},width:260}]
const equipmentColumns=[{title:'设备编号',key:'equipment_code',width:115},{title:'设备名称',key:'equipment_name',width:150},{title:'类型',key:'equipment_type_label',width:100},{title:'位置时间',render:(r:EquipmentRiskLink)=>fmt(r.recorded_at),width:160},{title:'所在区域',render:(r:EquipmentRiskLink)=>r.work_area_names.join('、')||'未命中所属项目区域',width:180,ellipsis:{tooltip:true}},{title:'点位水害类别',render:(r:EquipmentRiskLink)=>h(NTag,{type:r.risk_class==='HIGH_ATTENTION_AREA'?'error':r.risk_class==='INSPECTION_AREA'?'warning':r.risk_class==='GENERAL_WATER_AREA'?'success':'default'},{default:()=>r.risk_label}),width:150},{title:'区域影响',render:(r:EquipmentRiskLink)=>r.work_area_impact_level||'--',width:120},{title:'位置时效',render:(r:EquipmentRiskLink)=>r.position_status==='stale'?'位置已过期':'位置有效',width:105},{title:'时间差',render:(r:EquipmentRiskLink)=>r.time_difference_hours==null?'--':`${r.time_difference_hours.toFixed(1)} 小时`,width:100},{title:'辅助提示',key:'advice_text',width:280,ellipsis:{tooltip:true}}]
const terrainColumns=[{title:'DEM',key:'dem_name'},{title:'水害区域',key:'zone'},{title:'平均高程',render:(r:any)=>r.mean_elevation==null?'--':`${r.mean_elevation.toFixed(2)} m`},{title:'平均坡度',render:(r:any)=>r.mean_slope==null?'--':`${r.mean_slope.toFixed(2)}°`},{title:'低高程重叠',render:(r:any)=>pct(r.low_elevation_ratio)},{title:'规则版本',key:'version'}]
const uavOverlayColumns=[{title:'无人机影像',key:'uav_name'},{title:'采集时间',render:(r:UavRiskOverlay)=>r.uav_capture_time?fmt(r.uav_capture_time):'未填写'},{title:'高关注覆盖',render:(r:UavRiskOverlay)=>pct(r.high_attention_coverage_ratio)},{title:'重点巡检覆盖',render:(r:UavRiskOverlay)=>pct(r.inspection_coverage_ratio)},{title:'时间差',render:(r:UavRiskOverlay)=>r.time_difference_hours==null?'时间参考受限':`${r.time_difference_hours>=0?'晚':'早'} ${Math.abs(r.time_difference_hours).toFixed(1)} 小时`},{title:'版本',key:'analysis_version'}]
const verificationColumns=[{title:'区域',render:(r:UavVerification)=>r.work_area_name||'未指定区域'},{title:'影像',key:'uav_name'},{title:'状态',key:'verification_status_label'},{title:'人工观察',key:'observation_type_label'},{title:'说明',render:(r:UavVerification)=>r.finding_text||'未填写',ellipsis:{tooltip:true}},{title:'复核时间',render:(r:UavVerification)=>r.verified_at?fmt(r.verified_at):'未记录'}]
function stopAI(){aiVersion++;controller?.abort();controller=null;aiRunning.value=false}
async function explain(){if(!current.value)return;const version=++aiVersion;controller=new AbortController();aiText.value='';aiRunning.value=true;try{await streamRiskAI(current.value.id,t=>{if(version===aiVersion)aiText.value+=t},controller.signal)}catch(e:any){if(e?.name!=='AbortError')msg.error(e.message)}finally{if(version===aiVersion){aiRunning.value=false;controller=null}}}
watch(currentProjectId,()=>void loadHistory());onMounted(async()=>{try{[changes.value,projects.value,dems.value]=await Promise.all([api.changeAnalyses(),api.projects(),api.demDatasets(),loadHistory()])}catch(e:any){msg.error(e.message)}});onBeforeUnmount(stopAI)
</script>

